class Menu{"use strict";navbar=null;menu=null;menuButton=null;#lastScrollTop=0;constructor(){this.navbar=document.getElementById("navbar"),this.menu=document.getElementById("mobile-menu"),this.menuButton=document.getElementById("mobile-menu-button"),this.menuButton.addEventListener("click",this.toggle.bind(this)),window.addEventListener("scroll",function(){var t;window.matchMedia("(width >= 64rem)").matches||((t=window.pageYOffset||document.documentElement.scrollTop)>this.lastScrollTop?this.navbar.classList.add("-top-24!"):this.navbar.classList.remove("-top-24!"),this.lastScrollTop=t)},!1)}toggle(){this.menu.classList.contains("is-active")?this.hide():this.show()}show(){this.menu.classList.add("is-active"),document.body.classList.add("overflow-hidden")}hide(){this.menu.classList.remove("is-active"),document.body.classList.remove("overflow-hidden")}submenu(t){console.log("submenu",t)}}